""" #> IMPORTS =======================
================================== """

#> imports
import os
import sys
import numpy as np
import matplotlib.pyplot as plt

#> adding opus path
sys.path.insert(0, '../opus')

#> modules
import generate
import modules.parse as parse

#> declarations
outFolder = '../../arrival_order/data/increment' # increment data

#> profile subscripts (nfw, hern, ex; mult --> <order>)
PROFILES = {'nfw':  r'\bullet',
            'hern': r'\star',
            'ex':   r'\gamma'}

#> param symbols (%s --> profile subscript)
SYMBOLS = {'axisrat': r'q_{%s}',
           'theta':   r'\theta_{%s}',
           'x0':      r'x_{0,%s}',
           'y0':      r'y_{0,%s}',
           'norm':    r'a_{%s}'}

#> multipole param symbols (%s --> multipole order)
MULT = {'norm':  r'a_{%s}',
        'theta': r'\theta_{m_%s}'}

#> labels that don't follow the pattern
SPECIAL = {'both_axisrat': r'q_{\bullet} = q_{\star}',
           'ex_norm':      r'\gamma'}


""" #> LOADING =======================
================================== """

#> main run folder
def run_dir(outFolder):
    return generate.dataDir + outFolder

#> loads main run folder files
def load_run(outFolder):
    return parse.load(run_dir(outFolder))

#> loads every bin of every incremented param
def load_param(outFolder, folder):
    return parse.load_folders(os.path.join(run_dir(outFolder), folder))


""" #> READS DATA ====================
================================== """

#> loads the whole increment.py run
def read(**kwargs):

    #> kwargs
    outFolder = kwargs.get('outFolder', globals()['outFolder'])  # run folder (inside generate.dataDir)

    #> run info + redraws
    run = load_run(outFolder)

    #> every param: {folder: [bin 0, bin 1, ...]}
    data = {folder: load_param(outFolder, folder) for folder in run['info']['points']}

    return run, data


""" #> ANALYZE FNS ===================
================================== """

#> number of quads whose morph order matches the fermat order, per bin
def count_match(b_data):
    return [int(np.nansum(data['order_match'])) for data in b_data] # nan (non-quads) skipped


#> number of quads per bin (order_match is nan for non-quads)
def count_quads(b_data):
    return [int(np.sum(~np.isnan(data['order_match']))) for data in b_data]


#> profile subscript of a param folder (e.g., nfw_theta --> \bullet, mult_m3_norm --> 3)
def subscript(folder):
    prof, *rest = folder.split('_')
    if prof in ['mult']: return rest[0][1:]
    return PROFILES[prof]


#> returns x label of a param folder (e.g., nfw_theta --> $\theta_{\bullet}$)
def labels(folder):
    
    #> special cases
    if folder in SPECIAL: return f'${SPECIAL[folder]}$'
    
    #> symbol + profile subscript
    prof, param = folder.split('_')[0], folder.split('_')[-1]
    symbols = MULT if prof in ['mult'] else SYMBOLS
    return f'${symbols[param] % subscript(folder)}$'


#> order_match vs. inc param value
def order_match(run, folder, b_data):
    
    #> bin values + match counts
    x = run['info']['points'][folder]
    print(folder)
    y = np.array(count_match(b_data)) / np.array(count_quads(b_data)) # fraction of quads
    
    #> initializing plot
    fig, ax = plt.subplots(1,1,figsize=(6,6))
    ax.grid(ls=':', alpha=0.5)
    ax.set_xlabel(labels(folder), fontsize=15, fontweight='bold', labelpad=10)
    ax.set_ylabel('% Match', fontsize=15, fontweight='bold', labelpad=10)
    ax.set_ylim(0,1.1)
    
    #> plotting
    ax.axhline(1.0, c='k', ls=':')
    ax.plot(x, y, marker='o')
        
    plt.show()
    plt.close()
    
    return

#> order_match vs. inc param value, every param in one figure
def order_match_all(run, data, ncols=4):
    
    #> panel grid
    nrows = int(np.ceil(len(data) / ncols))
    fig, axes = plt.subplots(nrows, ncols, figsize=(4*ncols, 3.5*nrows), sharey=True)
    axes = axes.flatten()
    
    #> iterating through each param
    for ax, (folder, b_data) in zip(axes, data.items()):
        
        #> bin values + match fraction
        x = run['info']['points'][folder]
        y = np.array(count_match(b_data)) / np.array(count_quads(b_data)) # fraction of quads
        
        #> plotting
        ax.grid(ls=':', alpha=0.5)
        ax.axhline(1.0, c='k', ls=':')
        ax.plot(x, y, marker='o')
        ax.set_xlabel(labels(folder), fontsize=15, labelpad=5)
        ax.set_ylim(0,1.1)
    
    #> y labels (first column) + removing empty panels
    for ax in axes[::ncols]:          ax.set_ylabel('% Match', fontsize=15, fontweight='bold')
    for ax in axes[len(data):]:       ax.remove()
    
    fig.tight_layout()
    plt.show()
    plt.close()
    
    return

""" #> MAIN ==========================
================================== """

#> main function
if __name__ == '__main__':

    #> name
    print('> '+os.path.basename(__file__))

    #> loading
    run, data = read(outFolder=outFolder)
    
    print(run.keys())

    #> example: fraction of quads whose morph order matches the fermat order, per bin
    for folder, b_data in data.items():
        
        order_match(run, folder, b_data)

    #> every param together
    order_match_all(run, data)

    # end
# thank
